// SWIG Lua runtime, reconstructed using DWARF and the sibling source.
#include "Contrib/Contrib/lua/src/lua.h"

struct swig_type_info;
struct swig_cast_info;
typedef void *(*swig_converter_func)(void *);

typedef swig_type_info *(*swig_dycast_func)(void **);

struct swig_type_info {  // size 0x30
    const char * name;  // 0x00
    const char * str;  // 0x08
    swig_dycast_func dcast;  // 0x10
    swig_cast_info * cast;  // 0x18
    void * clientdata;  // 0x20
    int owndata;  // 0x28
};
static_assert(sizeof(swig_type_info) == 0x30, "swig_type_info");

typedef swig_type_info swig_type_info;

struct swig_cast_info {  // size 0x20
    swig_type_info * type;  // 0x00
    swig_converter_func converter;  // 0x08
    swig_cast_info * next;  // 0x10
    swig_cast_info * prev;  // 0x18
};
static_assert(sizeof(swig_cast_info) == 0x20, "swig_cast_info");

typedef swig_cast_info swig_cast_info;

struct swig_module_info {  // size 0x30
    swig_type_info ** types;  // 0x00
    size_t size;  // 0x08
    swig_module_info * next;  // 0x10
    swig_type_info ** type_initial;  // 0x18
    swig_cast_info ** cast_initial;  // 0x20
    void * clientdata;  // 0x28
};
static_assert(sizeof(swig_module_info) == 0x30, "swig_module_info");

typedef swig_module_info swig_module_info;

typedef struct {  // size 0x18
    const char * name;  // 0x00
    lua_CFunction get;  // 0x08
    lua_CFunction set;  // 0x10
} swig_lua_var_info;

typedef struct {  // size 0x30
    int type;  // 0x00
    char * name;  // 0x08
    long int lvalue;  // 0x10
    double dvalue;  // 0x18
    void * pvalue;  // 0x20
    swig_type_info ** ptype;  // 0x28
} swig_lua_const_info;

typedef struct {  // size 0x10
    const char * name;  // 0x00
    lua_CFunction method;  // 0x08
} swig_lua_method;

typedef struct {  // size 0x18
    const char * name;  // 0x00
    lua_CFunction getmethod;  // 0x08
    lua_CFunction setmethod;  // 0x10
} swig_lua_attribute;

struct swig_lua_class {  // size 0x38
    const char * name;  // 0x00
    swig_type_info ** type;  // 0x08
    lua_CFunction constructor;  // 0x10
    void (*destructor)(void *);  // 0x18
    swig_lua_method * methods;  // 0x20
    swig_lua_attribute * attributes;  // 0x28
    swig_lua_class ** bases;  // 0x30
};
static_assert(sizeof(swig_lua_class) == 0x38, "swig_lua_class");

typedef swig_lua_class swig_lua_class;

typedef struct {  // size 0x18
    void * ptr;  // 0x00
    swig_type_info * type;  // 0x08
    int own;  // 0x10
} swig_lua_userdata;


// Original LuaScriptInterface_wrap.cpp:425.
static swig_cast_info *SWIG_TypeCheck(const char *c, swig_type_info *ty)
{
    if (!ty) return 0;
    swig_cast_info *iter = ty->cast;
    while (iter) {
        if (strcmp(iter->type->name,c)==0) {
            if (iter == ty->cast) return iter;
            iter->prev->next=iter->next;
            if (iter->next) iter->next->prev=iter->prev;
            iter->next=ty->cast;
            iter->prev=0;
            if (ty->cast) ty->cast->prev=iter;
            ty->cast=iter;
            return iter;
        }
        iter=iter->next;
    }
    return 0;
}

// Original LuaScriptInterface_wrap.cpp:431.
static inline swig_cast_info *SWIG_TypeCheckStruct(swig_type_info *from, swig_type_info *into)
{
    if (into) {
        swig_cast_info *iter = into->cast;
        while (iter) {
            if (iter->type == from) {
                if (iter == into->cast) {
                    return iter;
                }
                /* Move iter to the top of the linked list */
                iter->prev->next = iter->next;
                if (iter->next) {
                    iter->next->prev = iter->prev;
                }
                iter->next = into->cast;
                iter->prev = 0;
                if (into->cast) {
                    into->cast->prev = iter;
                }
                into->cast = iter;
                return iter;
            }
            iter = iter->next;
        }
    }
    return 0;
}

// Original LuaScriptInterface_wrap.cpp:439.
static inline void *SWIG_TypeCast(swig_cast_info *ty, void *ptr)
{
    return ((!ty) || (!ty->converter)) ? ptr : (*ty->converter)(ptr);
}

// Original LuaScriptInterface_wrap.cpp:491.
static void SWIG_TypeClientData(swig_type_info *ti, void *clientdata)
{
    swig_cast_info *cast = ti->cast;

    ti->clientdata = clientdata;

    while (cast) {
        if (!cast->converter) {
            swig_type_info *tc = cast->type;
            if (!tc->clientdata) {
                SWIG_TypeClientData(tc, clientdata);
            }
        }
        cast = cast->next;
    }
}

// Original LuaScriptInterface_wrap.cpp:521.
static swig_type_info *SWIG_MangledTypeQueryModule(swig_module_info *start,swig_module_info *end,const char *name)
{
    swig_module_info *iter=start;
    do {
        if (iter->size) {
            size_t l=0,r=iter->size-1;
            do {
                size_t i=(l+r)/2;
                const char *iname=iter->types[i]->name;
                if (iname) {
                    int compare=strcmp(name,iname);
                    if (!compare) return iter->types[i];
                    else if (compare<0) {
                        if (!i) break;
                        r=i-1;
                    } else l=i+1;
                } else break;
            } while (l<=r);
        }
        iter=iter->next;
    } while (iter!=end);
    return 0;
}

// Original LuaScriptInterface_wrap.cpp:790.
static void SWIG_Lua_add_function(lua_State *L, const char *name, lua_CFunction fn)
{
    lua_pushstring(L, name);
    lua_pushcfunction(L, fn);
    lua_rawset(L, -3);
}

// Original LuaScriptInterface_wrap.cpp:791.
static void SWIG_Lua_get_table(lua_State *L, const char *name)
{
    lua_pushstring(L, name);
    lua_rawget(L, -2);
}

// Original LuaScriptInterface_wrap.cpp:810.
static int SWIG_Lua_module_get(lua_State *L)
{
/*  there should be 2 params passed in
    (1) table (not the meta table)
    (2) string name of the attribute
*/
    /* get the metatable */
    lua_getmetatable(L, 1);
    SWIG_Lua_get_table(L, ".get");  /* get the .get table */
    lua_remove(L, 3);               /* remove the metatable */
    if (lua_istable(L, -1)) {
        lua_pushvalue(L, 2);        /* key */
        lua_rawget(L, -2);          /* look for the fn */
        lua_remove(L, 3);           /* remove .get */
        if (lua_iscfunction(L, -1)) {
            /* found it so call the fn & return its value */
            lua_call(L, 0, 1);
            return 1;
        }
        lua_pop(L, 1);              /* remove the top */
    }
    lua_pop(L, 1);                  /* remove the metatable */
    lua_pushnil(L);
    return 1;
}

// Original LuaScriptInterface_wrap.cpp:844.
static int SWIG_Lua_module_set(lua_State *L)
{
/*  there should be 3 params passed in
    (1) table (not the meta table)
    (2) string name of the attribute
    (3) any for the new value
*/
    /* get the metatable */
    lua_getmetatable(L, 1);
    SWIG_Lua_get_table(L, ".set");  /* get the .set table */
    lua_remove(L, 4);               /* remove the metatable */
    if (lua_istable(L, -1)) {
        lua_pushvalue(L, 2);        /* key */
        lua_rawget(L, -2);          /* look for the fn */
        lua_remove(L, 4);           /* remove .set */
        if (lua_iscfunction(L, -1)) {
            /* found it so call the fn & return its value */
            lua_pushvalue(L, 3);    /* value */
            lua_call(L, 1, 0);
            return 0;
        }
        lua_pop(L, 1);              /* remove the top */
    }
    lua_pop(L, 1);                  /* remove the metatable */
    return 0;
}

// Original LuaScriptInterface_wrap.cpp:876.
static void SWIG_Lua_module_begin(lua_State *L,const char *name)
{
    lua_pushstring(L,name);
    lua_newtable(L);
    lua_newtable(L);
    SWIG_Lua_add_function(L,"__index",SWIG_Lua_module_get);
    SWIG_Lua_add_function(L,"__newindex",SWIG_Lua_module_set);
    lua_pushstring(L,".get"); lua_newtable(L); lua_rawset(L,-3);
    lua_pushstring(L,".set"); lua_newtable(L); lua_rawset(L,-3);
    lua_setmetatable(L,-2);
    lua_rawset(L,-3);
    lua_pushstring(L,name);
    lua_rawget(L,-2);
}

// Original LuaScriptInterface_wrap.cpp:903.
static void SWIG_Lua_module_add_variable(lua_State *L,const char *name,lua_CFunction getFn,lua_CFunction setFn)
{
    lua_getmetatable(L,-1);
    if (getFn) {
        lua_pushstring(L,".get");lua_rawget(L,-2);
        SWIG_Lua_add_function(L,name,getFn);lua_pop(L,1);
    }
    if (setFn) {
        lua_pushstring(L,".set");lua_rawget(L,-2);
        SWIG_Lua_add_function(L,name,setFn);lua_pop(L,1);
    }
    lua_pop(L,1);
}

// Original LuaScriptInterface_wrap.cpp:923.
static void SWIG_Lua_module_add_function(lua_State *L,const char *name,lua_CFunction fn)
{
    lua_pushstring(L,name);lua_pushcfunction(L,fn);lua_rawset(L,-3);
}

// Original LuaScriptInterface_wrap.cpp:933.
static int SWIG_Lua_class_get(lua_State *L)
{
/*  there should be 2 params passed in
    (1) userdata (not the meta table)
    (2) string name of the attribute
*/
    lua_getmetatable(L, -2);        /* get the meta table */
    SWIG_Lua_get_table(L, ".get");  /* find the .get table */
    /* look for the key in the .get table */
    lua_pushvalue(L, 2);            /* key */
    lua_rawget(L, -2);
    lua_remove(L, -2);              /* stack tidy, remove .get table */
    if (lua_iscfunction(L, -1)) {
        /* found it so call the fn & return its value */
        lua_pushvalue(L, 1);        /* the userdata */
        lua_call(L, 1, 1);          /* 1 value in (userdata), 1 out (result) */
        lua_remove(L, -2);          /* stack tidy, remove metatable */
        return 1;
    }
    lua_pop(L, 1);                  /* remove the answer (nil) */
    /* ok, so try the .fn table */
    SWIG_Lua_get_table(L, ".fn");   /* find the .fn table */
    lua_pushvalue(L, 2);            /* key */
    lua_rawget(L, -2);              /* look for the fn */
    lua_remove(L, -2);              /* stack tidy, remove .fn table */
    if (lua_iscfunction(L, -1)) {
        /* found it so return the fn & let lua call it */
        lua_remove(L, -2);          /* stack tidy, remove metatable */
        return 1;
    }
    lua_pop(L, 1);                  /* remove the answer (nil) */
    /* NEW: looks for the __getitem() fn -- a user provided get fn */
    SWIG_Lua_get_table(L, "__getitem");
    if (lua_iscfunction(L, -1)) {
        lua_pushvalue(L, 1);        /* the userdata */
        lua_pushvalue(L, 2);        /* the parameter */
        lua_call(L, 2, 1);          /* 2 values in (userdata, key), 1 out */
        lua_remove(L, -2);          /* stack tidy, remove metatable */
        return 1;
    }
    return 0;
}

// Original LuaScriptInterface_wrap.cpp:983.
static int SWIG_Lua_class_set(lua_State *L)
{
/*  there should be 3 params passed in
    (1) table (not the meta table)
    (2) string name of the attribute
    (3) any for the new value
*/
    lua_getmetatable(L, 1);         /* get the meta table */

    SWIG_Lua_get_table(L, ".set");  /* find the .set table */
    if (lua_istable(L, -1)) {
        /* look for the key in the .set table */
        lua_pushvalue(L, 2);        /* key */
        lua_rawget(L, -2);
        if (lua_iscfunction(L, -1)) {
            /* found it so call the fn & return its value */
            lua_pushvalue(L, 1);    /* userdata */
            lua_pushvalue(L, 3);    /* value */
            lua_call(L, 2, 0);
            return 0;
        }
        lua_pop(L, 1);              /* remove the value */
    }
    lua_pop(L, 1);                  /* remove the value .set table */
    /* NEW: looks for the __setitem() fn -- a user provided set fn */
    SWIG_Lua_get_table(L, "__setitem");
    if (lua_iscfunction(L, -1)) {
        lua_pushvalue(L, 1);        /* the userdata */
        lua_pushvalue(L, 2);        /* the parameter */
        lua_pushvalue(L, 3);        /* the value */
        lua_call(L, 3, 0);          /* 3 values in, 0 out */
        lua_remove(L, -2);          /* stack tidy, remove metatable */
        return 1;
    }
    return 0;
}

// Original LuaScriptInterface_wrap.cpp:1030.
static int SWIG_Lua_class_destruct(lua_State *L)
{
/*  there should be 1 param passed in
    (1) userdata (not the meta table) */
    swig_lua_userdata *usr;
    swig_lua_class *clss;

    usr = (swig_lua_userdata *)lua_touserdata(L, -1);   /* get it */
    /* if must be destroyed & has a destructor */
    if (usr->own) {
        clss = (swig_lua_class *)usr->type->clientdata; /* get the class */
        if (clss && clss->destructor) {
            clss->destructor(usr->ptr);
        }
    }
    return 0;
}

// Original LuaScriptInterface_wrap.cpp:1051.
static void SWIG_Lua_get_class_registry(lua_State *L)
{
    lua_pushstring(L, "SWIG");      /* get the registry */
    lua_rawget(L, LUA_REGISTRYINDEX);
    if (!lua_istable(L, -1)) {      /* not there */
        lua_pop(L, 1);
        lua_pushstring(L, "SWIG");
        lua_newtable(L);
        lua_rawset(L, LUA_REGISTRYINDEX);

        lua_pushstring(L, "SWIG");
        lua_rawget(L, LUA_REGISTRYINDEX);
    }
}

// Original LuaScriptInterface_wrap.cpp:1069.
static void SWIG_Lua_get_class_metatable(lua_State *L, const char *cname)
{
    SWIG_Lua_get_class_registry(L); /* get the registry */
    lua_pushstring(L, cname);       /* get the name */
    lua_rawget(L, -2);              /* get the metatable itself */
    lua_remove(L, -2);              /* tidy up (remove registry) */
}

// Original LuaScriptInterface_wrap.cpp:1078.
static void SWIG_Lua_add_class_variable(lua_State *L, const char *name,
                                        lua_CFunction getFn, lua_CFunction setFn)
{
    SWIG_Lua_get_table(L, ".get");  /* find the .get table */
    SWIG_Lua_add_function(L, name, getFn);
    lua_pop(L, 1);                  /* tidy stack (remove table) */
    if (setFn) {
        SWIG_Lua_get_table(L, ".set");  /* find the .set table */
        SWIG_Lua_add_function(L, name, setFn);
        lua_pop(L, 1);              /* tidy stack (remove table) */
    }
}

// Original LuaScriptInterface_wrap.cpp:1095.
static void SWIG_Lua_add_class_details(lua_State *L, swig_lua_class *clss)
{
    int i;
    /* add its parent methods */
    for (i = 0; clss->bases[i]; i++) {
        SWIG_Lua_add_class_details(L, clss->bases[i]);
    }
    /* add attributes */
    for (i = 0; clss->attributes[i].name; i++) {
        SWIG_Lua_add_class_variable(L, clss->attributes[i].name,
                                    clss->attributes[i].getmethod,
                                    clss->attributes[i].setmethod);
    }
    /* add methods to the metatable */
    SWIG_Lua_get_table(L, ".fn");   /* find the .fn table */
    for (i = 0; clss->methods[i].name; i++) {
        lua_pushstring(L, clss->methods[i].name);
        lua_pushcfunction(L, clss->methods[i].method);
        lua_rawset(L, -3);
    }
    lua_pop(L, 1);                  /* tidy stack (remove table) */
    /* add operator overloads: any method whose name starts with "__" */
    for (i = 0; clss->methods[i].name; i++) {
        if (clss->methods[i].name[0] == '_' && clss->methods[i].name[1] == '_') {
            lua_pushstring(L, clss->methods[i].name);
            lua_pushcfunction(L, clss->methods[i].method);
            lua_rawset(L, -3);
        }
    }
}

// Original LuaScriptInterface_wrap.cpp:1126.
static void SWIG_Lua_class_register(lua_State *L,swig_lua_class *clss)
{
    if (clss->constructor) {
        lua_pushstring(L,clss->name);
        lua_pushcfunction(L,clss->constructor);
        lua_rawset(L,-3);
    }
    SWIG_Lua_get_class_registry(L);
    lua_pushstring(L,clss->name);
    lua_newtable(L);
    lua_pushstring(L,".type");lua_pushstring(L,clss->name);lua_rawset(L,-3);
    lua_pushstring(L,".get");lua_newtable(L);lua_rawset(L,-3);
    lua_pushstring(L,".set");lua_newtable(L);lua_rawset(L,-3);
    lua_pushstring(L,".fn");lua_newtable(L);lua_rawset(L,-3);
    SWIG_Lua_add_function(L,"__index",SWIG_Lua_class_get);
    SWIG_Lua_add_function(L,"__newindex",SWIG_Lua_class_set);
    SWIG_Lua_add_function(L,"__gc",SWIG_Lua_class_destruct);
    lua_rawset(L,-3);lua_pop(L,1);
    SWIG_Lua_get_class_metatable(L,clss->name);
    SWIG_Lua_add_class_details(L,clss);
    lua_pop(L,1);
}

// Original LuaScriptInterface_wrap.cpp:1172.
static void SWIG_Lua_NewPointerObj(lua_State *L, void *ptr, swig_type_info *type, int own)
{
    swig_lua_userdata *usr;
    if (!ptr) {
        lua_pushnil(L);
        return;
    }
    usr = (swig_lua_userdata *)lua_newuserdata(L, sizeof(swig_lua_userdata));  /* get data */
    usr->ptr = ptr;                 /* set the ptr */
    usr->type = type;
    usr->own = own;
    if (type->clientdata) {         /* there is clientdata: so add the metatable */
        SWIG_Lua_get_class_metatable(L, ((swig_lua_class *)(type->clientdata))->name);
        if (lua_istable(L, -1)) {
            lua_setmetatable(L, -2);
        } else {
            lua_pop(L, 1);
        }
    }
}

// Original LuaScriptInterface_wrap.cpp:1199.
static int SWIG_Lua_ConvertPtr(lua_State *L, int index, void **ptr,
                               swig_type_info *type, int flags)
{
    swig_lua_userdata *usr;
    swig_cast_info *cast;

    usr = (swig_lua_userdata *)lua_touserdata(L, index); /* get data */
    if (usr) {
        cast = SWIG_TypeCheckStruct(usr->type, type);       /* normal type checking */
        if (cast) {
            *ptr = SWIG_TypeCast(cast, usr->ptr);
            return 0;
        }
    }
    return 1; // SWIG 1.3.29 uses nonzero for conversion failure.
}

// Original LuaScriptInterface_wrap.cpp:1216.
static void *SWIG_Lua_MustGetPtr(lua_State *L, int index, swig_type_info *type,
                                 int flags, int argnum, const char *func_name)
{
    void *result;
    if (SWIG_Lua_ConvertPtr(L, index, &result, type, flags)) {
        lua_pushfstring(L, "Error in %s, expected a %s at argument number %d\n",
                        func_name, (type && type->str) ? type->str : "void*", argnum);
        lua_error(L);
    }
    return result;
}

// Original LuaScriptInterface_wrap.cpp:1228.
static int SWIG_Lua_type(lua_State *L)
{
    if (lua_isuserdata(L, 1)) {
        swig_lua_userdata *usr;
        usr = (swig_lua_userdata *)lua_touserdata(L, 1);    /* get data */
        lua_pushstring(L, usr->type->name);
        return 1;
    }
    return 0;
}

// Original LuaScriptInterface_wrap.cpp:1241.
static int SWIG_Lua_equal(lua_State *L)
{
    swig_lua_userdata *usr1, *usr2;

    if (lua_isuserdata(L, 1) && lua_isuserdata(L, 2)) {
        usr1 = (swig_lua_userdata *)lua_touserdata(L, 1);
        usr2 = (swig_lua_userdata *)lua_touserdata(L, 2);
        int result = (usr1->ptr == usr2->ptr && usr1->type == usr2->type);
        lua_pushboolean(L, result);
        return 1;
    }
    return 0;
}

// Original LuaScriptInterface_wrap.cpp:1261.
static void SWIG_Lua_InstallConstants(lua_State *L,swig_lua_const_info *constants)
{
    for (;constants->type;constants++) {
        switch (constants->type) {
        case 1:lua_pushstring(L,constants->name);lua_pushnumber(L,(lua_Number)constants->lvalue);lua_rawset(L,-3);break;
        case 2:lua_pushstring(L,constants->name);lua_pushnumber(L,(lua_Number)constants->dvalue);lua_rawset(L,-3);break;
        case 3:lua_pushstring(L,constants->name);lua_pushstring(L,(char *)constants->pvalue);lua_rawset(L,-3);break;
        case 4:lua_pushstring(L,constants->name);SWIG_Lua_NewPointerObj(L,constants->pvalue,*constants->ptype,0);lua_rawset(L,-3);break;
        }
    }
}

